 async function saveMedicine(e:React.FormEvent){e.preventDefault();const clinicId=getActiveClinicId();if(!supabase||!clinicId){setMsg('Sign in and select a clinic first.');return}const tax=Number(form.tax_percent);if(!Number.isFinite(tax)||tax<0||tax>100){setMsg('GST/tax must be between 0 and 100%.');return}setBusy(true);const payload={name:form.name.trim(),generic_name:form.generic_name.trim()||null,strength:form.strength.trim()||null,dosage_form:form.dosage_form,reorder_level:Number(form.reorder_level),tax_percent:tax,product_category:form.product_category,sku:form.sku.trim()||null,hsn_code:form.hsn_code.trim()||null,unit_name:form.unit_name,manufacturer:form.manufacturer.trim()||null};const q=editingMedicine?supabase.from('medications').update(payload).eq('id',editingMedicine).eq('clinic_id',clinicId):supabase.from('medications').insert({...payload,clinic_id:clinicId,active:true});const {data,error}=await q.select('id,name,generic_name,strength,dosage_form,reorder_level,tax_percent,active,product_category,sku,hsn_code,unit_name,manufacturer').single();if(error)setMsg(error.message);else if(data){setItems(old=>editingMedicine?old.map(m=>m.id===editingMedicine?data as Medicine:m):[...old,data as Medicine]);if(!editingMedicine)setStock(old=>({...old,medication_id:data.id}));setShowMedicine(false);setEditingMedicine(null);setForm({name:'',generic_name:'',strength:'',dosage_form:'Tablet',reorder_level:'10',tax_percent:'5',product_category:'Medicine',sku:'',hsn_code:'',unit_name:'Strip',manufacturer:''});setMsg(editingMedicine?'Medicine updated.':'Medicine master saved. Receive a batch to add stock.')}setBusy(false)}
