 async function editBatch(b:Batch){const clinicId=getActiveClinicId();if(!supabase||!clinicId)return;const qty=window.prompt(`Verified physical quantity for ${b.batch_number}`,String(b.quantity_on_hand));if(qty===null)return;const n=Number(qty);if(!Number.isFinite(n)||n<0){setMsg('Quantity must be zero or greater.');return}const reason=window.prompt('Adjustment reason: Physical count correction, Damaged stock, Expired stock, Breakage, Opening balance correction, Other','Physical count correction');if(!reason)return;const notes=window.prompt('Optional audit note','')||'';const rate=window.prompt('Sale rate per unit (₹)',String(b.sale_rate));if(rate===null)return;const r=Number(rate);if(!Number.isFinite(r)||r<0){setMsg('Sale rate must be zero or greater.');return}const supplier=window.prompt('Supplier name',b.supplier_name||'');if(supplier===null)return;setBusy(true);const {error:adjError}=await supabase.rpc('adjust_pharmacy_batch',{p_clinic_id:clinicId,p_batch_id:b.id,p_new_quantity:n,p_reason:reason,p_notes:notes});if(adjError){setMsg(adjError.message);setBusy(false);return}const {error}=await supabase.from('inventory_batches').update({sale_rate:r,supplier_name:supplier.trim()||null}).eq('id',b.id).eq('clinic_id',clinicId);if(error)setMsg(error.message);else{setMsg('Stock correction saved with audit movement.');await reload()}setBusy(false)}
