 async function saveSupplier(e:React.FormEvent){e.preventDefault();const clinicId=getActiveClinicId();if(!supabase||!clinicId)return;setSupplierBusy(true);const {data,error}=await supabase.from('pharmacy_suppliers').insert({...supplierForm,clinic_id:clinicId,supplier_name:supplierForm.supplier_name.trim(),phone:supplierForm.phone.trim()||null,email:supplierForm.email.trim()||null,gstin:supplierForm.gstin.trim().toUpperCase()||null,address:supplierForm.address.trim()||null,notes:supplierForm.notes.trim()||null,active:true}).select('id,supplier_name,phone,email,gstin,address,notes,active').single();if(error)setMsg(error.message);else{setSuppliers(old=>[...old,data as Supplier].sort((a,b)=>a.supplier_name.localeCompare(b.supplier_name)));setSupplierForm({supplier_name:'',phone:'',email:'',gstin:'',address:'',notes:''});setMsg('Supplier saved for this clinic. Use the same supplier name in stock receipts for supplier-wise valuation.')}setSupplierBusy(false)}
